    lib = 'class Sach:\n    def __init__(self, ma, ten, tac_gia):\n        self.ma = ma\n        self.ten = ten\n        self.tac_gia = tac_gia\n        self.dang_muon = False\n    def __str__(self):\n        tt = "đang mượn" if self.dang_muon else "còn"\n        return f"[{self.ma}] {self.ten} - {self.tac_gia} ({tt})"\n\nclass ThuVien:\n    def __init__(self):\n        self.ds = []\n    def them(self, sach):\n        self.ds.append(sach)\n    def tim(self, ma):\n        for s in self.ds:\n            if s.ma == ma:\n                return s\n        return None\n    def muon(self, ma):\n        s = self.tim(ma)\n        if s is None or s.dang_muon:\n            return False\n        s.dang_muon = True\n        return True\n    def tra(self, ma):\n        s = self.tim(ma)\n        if s is None or not s.dang_muon:\n            return False\n        s.dang_muon = False\n        return True\n    def con_lai(self):\n        return [s for s in self.ds if not s.dang_muon]\n\ntv = ThuVien()\ntv.them(Sach(1, "Dế Mèn", "Tô Hoài"))\ntv.them(Sach(2, "Tắt đèn", "Ngô Tất Tố"))\ntv.them(Sach(3, "Lão Hạc", "Nam Cao"))\nprint(tv.muon(1))\nprint(tv.muon(1))\nprint(tv.muon(9))\nprint(tv.tra(1))\nprint(tv.tra(1))\nfor s in tv.ds:\n    print(s)\nprint(len(tv.con_lai()))'
