         trace_fig('Số sách còn lại sau từng thao tác', ['Sau thao tác', 'Đang mượn', 'Còn lại'], [('ban đầu (3 sách)', 0, 3), ('muon(2)', 1, 2), ('muon(2) lần nữa', 1, 2), ('tra(2)', 0, 3)], 'Mượn hai lần liên tiếp không làm số sách còn lại giảm thêm.', hl=[2]),
